<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Trip Cost Splitter</title>
<style>
:root { --surface-page:#fafaf8; --surface-elevated:#f4f3ee; --text-primary:#1a1a1a; --text-muted:#6b6b6b; --border-default:rgba(0,0,0,0.08); --accent:#c15f3c }
