<body>
<div class="wrap">
  <h1>Trip Cost Splitter</h1>
  <p class="sub">Log who paid for what on the weekend trip, then see exactly who owes whom.</p>

  <section class="card" aria-labelledby="add-h">
    <h2 id="add-h">Add an expense</h2>
    <form id="form" novalidate>
      <div class="row">
        <div>
          <label for="desc">What was it for?</label>
          <input id="desc" type="text" autocomplete="off" placeholder="e.g. Dinner, gas, tickets">
        </div>
        <div>
          <label for="amount">Amount</label>
          <input id="amount" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0.00">
        </div>
      </div>
      <div class="row" style="margin-top:10px">
        <div>
          <label for="payer">Who paid?</label>
          <select id="payer"></select>
        </div>
        <div>
          <label for="sharers">Who should share?</label>
          <select id="sharers"></select>
        </div>
      </div>
      <button type="submit" class="add">Add expense</button>
      <div class="err" id="err" role="alert"></div>
    </form>
  </section>

  <section class="card" aria-labelledby="list-h">
    <h2 id="list-h">Expenses</h2>
    <ul class="list" id="list"></ul>
    <div class="summary" id="summary" hidden>
      <span>Total spent</span>
      <span id="total"></span>
    </div>
  </section>

  <section class="card" aria-labelledby="settle-h">
    <h2 id="settle-h">Who owes whom</h2>
    <ul class="settle" id="settle"></ul>
    <div id="balances"></div>
  </section>

  <p class="sub" aria-live="polite" id="status"></p>
</div>
<script>
const PEOPLE = ['Levente', 'Anna', 'Peti'];
const KEY = 'trip-splitter-v1';
let expenses = [];

function money(n){ return new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(n); }
function esc(s){ return String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function fmtShare(sh){ return sh.length === PEOPLE.length ? 'Everyone' : sh.join(' & '); }

function compute(){
  const net = {}; PEOPLE.forEach(p => net[p] = 0);
  let total = 0;
  for(const e of expenses){
    total += e.amount;
    const share = e.amount / e.sharers.length;
    net[e.payer] += e.amount;
    for(const s of e.sharers) net[s] -= share;
  }
  PEOPLE.forEach(p => net[p] = Math.round(net[p] * 100) / 100);
  const creditors = PEOPLE.map(p => ({p, v: net[p]})).filter(x => x.v > 0.005).sort((a,b)=>b.v-a.v);
  const debtors = PEOPLE.map(p => ({p, v: -net[p]})).filter(x => x.v > 0.005).sort((a,b)=>b.v-a.v);
  const transfers = [];
  let i = 0, j = 0;
  while(i < debtors.length && j < creditors.length){
    const amt = Math.round(Math.min(debtors[i].v, creditors[j].v) * 100) / 100;
    if(amt > 0) transfers.push({from: debtors[i].p, to: creditors[j].p, amount: amt});
    debtors[i].v = Math.round((debtors[i].v - amt) * 100) / 100;
    creditors[j].v = Math.round((creditors[j].v - amt) * 100) / 100;
    if(debtors[i].v <= 0.005) i++;
    if(creditors[j].v <= 0.005) j++;
  }
  return {net, total, transfers};
}

function render(){
  const {net, total, transfers} = compute();
  const list = document.getElementById('list');
  if(expenses.length === 0){
    list.innerHTML = '<li class="empty">No expenses yet. Add your first one above to start splitting.</li>';
  } else {
    list.innerHTML = expenses.map((e,idx)=>`<li class="exp"><div class="exp-main"><div class="exp-title">${esc(e.desc)}</div><div class="exp-meta">${esc(e.payer)} paid &middot; shared with ${esc(fmtShare(e.sharers))}</div></div><div class="exp-amt">${money(e.amount)}</div><button class="del" data-del="${idx}" aria-label="Delete ${esc(e.desc)}">Remove</button></li>`).join('');
  }
  const sum = document.getElementById('summary');
  sum.hidden = expenses.length === 0;
  document.getElementById('total').textContent = money(total);

  const settle = document.getElementById('settle');
  if(expenses.length === 0){
    settle.innerHTML = '<li class="empty">Add expenses to see who owes whom.</li>';
  } else if(transfers.length === 0){
    settle.innerHTML = '<li class="empty">All settled up — nobody owes anyone.</li>';
  } else {
    settle.innerHTML = transfers.map(t=>`<li><span class="who">${esc(t.from)}</span> pays <span class="who">${esc(t.to)}</span> <span class="amt">${money(t.amount)}</span></li>`).join('');
  }

  const bal = document.getElementById('balances');
  if(expenses.length === 0){
    bal.innerHTML = '';
  } else {
    bal.innerHTML = '<div style="margin-top:14px;font-size:.8rem;color:var(--text-muted)">Net balance per person</div>' +
      PEOPLE.map(p=>{
        const v = net[p];
        const cls = v >= 0 ? 'pos' : 'neg';
        const txt = v >= 0 ? 'gets back ' + money(v) : 'owes ' + money(-v);
        return `<div class="bal"><span>${esc(p)}</span><span class="${cls}">${txt}</span></div>`;
      }).join('');
  }
}

function initSelects(){
  const payer = document.getElementById('payer');
  const sharers = document.getElementById('sharers');
  payer.innerHTML = PEOPLE.map(p=>`<option>${p}</option>`).join('');
  const all = PEOPLE.map(p=>`<option value="${p}">${p}</option>`).join('');
  const everyone = PEOPLE.map(p=>`<option value="${p}" selected>${p}</option>`).join('');
  sharers.innerHTML = `<option value="__all__" selected>Everyone</option><option value="__custom__">Choose people…</option>`;
  sharers.addEventListener('change', ()=>{
    if(sharers.value === '__custom__'){
      sharers.innerHTML = everyone;
      sharers.multiple = true;
      sharers.size = 3;
    }
  });
}

function getSelectedSharers(){
  const sel = document.getElementById('sharers');
  if(sel.multiple){
    return Array.from(sel.selectedOptions).map(o=>o.value);
  }
  return sel.value === '__all__' ? [...PEOPLE] : [sel.value];
}

function resetSharers(){
  const sel = document.getElementById('sharers');
  sel.multiple = false;
  sel.size = 1;
  sel.innerHTML = `<option value="__all__" selected>Everyone</option><option value="__custom__">Choose people…</option>`;
}

function setStatus(msg){ document.getElementById('status').textContent = msg; }

async function save(){
  if(window.alfy && window.alfy.storage){
    try { await window.alfy.storage.set(KEY, expenses); } catch(e){}
  }
}
async function load(){
  if(window.alfy && window.alfy.storage){
    try { const s = await window.alfy.storage.get(KEY); if(Array.isArray(s)) expenses = s; } catch(e){}
  }
}

document.getElementById('form').addEventListener('submit', (e)=>{
  e.preventDefault();
  const err = document.getElementById('err');
  const desc = document.getElementById('desc').value.trim();
  const amount = parseFloat(document.getElementById('amount').value);
  const payer = document.getElementById('payer').value;
  const sharers = getSelectedSharers();
  err.textContent = '';
  if(!desc){ err.textContent = 'Please describe what this was for.'; return; }
  if(!(amount > 0)){ err.textContent = 'Enter an amount greater than zero.'; return; }
  if(sharers.length === 0){ err.textContent = 'Select at least one person to share with.'; return; }
  expenses.push({desc, amount: Math.round(amount*100)/100, payer, sharers});
  save(); render();
  document.getElementById('desc').value = '';
  document.getElementById('amount').value = '';
  resetSharers();
  setStatus('Expense added.');
});

document.getElementById('list').addEventListener('click', (e)=>{
  const btn = e.target.closest('[data-del]');
  if(!btn) return;
  const idx = parseInt(btn.dataset.del, 10);
  const removed = expenses.splice(idx,1)[0];
  save(); render();
  setStatus('Removed "' + removed.desc + '".');
});

(async function init(){
  initSelects();
  await load();
  render();
})();
</script>
</body>
</html>
